import { PLACE_COORDS } from '@/lib/content/_place-coords.gen';

/**
 * Stored coordinates for tour itinerary stops and meeting points, generated by
 * `scripts/build-place-coords.mjs` (OpenStreetMap + hand-placed overrides, reviewed) — checked BEFORE
 * the billed Google geocoder, so a tour page normally costs zero Geocoding calls. Pure: no Maps JS.
 *
 * Why not cache Google's own geocodes? Google's terms don't allow storing them long-term; OSM data
 * (ODbL) may be stored with attribution, and a hand-placed pin is ours.
 */
export function normalisePlaceName(name: string): string {
  return name
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/,?\s*mauritius\s*$/, '')
    .replace(/[^a-z0-9+]+/g, ' ')
    .trim();
}

/**
 * `{lat,lng}` when the place is known; `null` when it is known to be UNPLACEABLE (a generic phrase
 * like "Pick-up at all parts of the island" — Google only ever answers those with the island
 * centroid, which the caller discards anyway, so asking is a wasted billed call); `undefined` when
 * the table doesn't know the name and the caller may still ask Google.
 */
export function lookupPlaceCoords(name: string): { lat: number; lng: number } | null | undefined {
  const key = normalisePlaceName(name);
  return Object.prototype.hasOwnProperty.call(PLACE_COORDS, key) ? PLACE_COORDS[key] : undefined;
}
